# POST /api/sheets/{sheetId}/periods/{periodId}/reopen — reopen a closed or soft-closed period, so its due-total is live again.
# Only a steward may reopen. A period not on the sheet or neither closed nor soft-closed, or a user who is not a steward, is a 400 and
# writes nothing. Responds with the period as stored.
validate:
  class: net.officefloor.hq.app.period.ValidatePeriodClose
  next: load
load:
  class: net.officefloor.hq.app.period.LoadPeriod
  govern: [ transaction ]
  next: reopen
reopen:
  class: net.officefloor.hq.app.period.ReopenPeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.RecordPeriodReopened
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/periods/{periodId}/close — close a period, fixing its due-total as it is now (later
# rate changes do not alter it). A period not on the sheet or already closed is a 400 and writes nothing. Once
# closed, no claim whose due-by falls inside it can be added, edited, opened, settled or voided. Responds with the period as
# stored.
validate:
  class: net.officefloor.hq.app.period.ValidatePeriodClose
  next: load
load:
  class: net.officefloor.hq.app.period.LoadPeriod
  govern: [ transaction ]
  next: close
close:
  class: net.officefloor.hq.app.period.ClosePeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.RecordPeriodClosed
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
  govern: [ transaction ]
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Val;

/** Reopens a closed or soft-closed period, so its due-total is live again. Only a role the sheet's reopen permission allows (a steward while it is blank) may reopen; reopening a period that is
 *  not closed is refused. */
public class ReopenPeriod {
    public void reopen(@Val Period period, @Val PeriodCloseRequest request, PeriodRepository periods,
            RoleRepository roles, SettingRepository settings) throws InvalidPeriodException {
        if (!settings.permits(period.sheetId(), "reopen", roles.roleOf(period.sheetId(), request.by()))) {
            throw new InvalidPeriodException("The sheet's permission does not let this user reopen a period");
        }
        if (!(period.closed() || period.soft()) || !periods.reopen(period)) {
            throw new InvalidPeriodException("The period " + period.name() + " is not closed");
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Writes PERIOD_REOPENED to the audit file once the period is reopened. */
public class RecordPeriodReopened {
    public void record(@Val Period period, @Val PeriodCloseRequest request, Audit audit) {
        audit.record("PERIOD_REOPENED sheet=" + period.sheetId() + " by=" + request.by() + " period=" + period.name());
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a period of the sheet by id; one not on the sheet is refused. */
public class LoadPeriod {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("periodId") String periodId,
            PeriodRepository periods, Out<Period> period) throws InvalidPeriodException {
        Period found;
        try {
            found = periods.find(sheetId.trim(), Long.parseLong(periodId.trim()));
        } catch (NumberFormatException e) {
            found = null;
        }
        if (found == null) {
            throw new InvalidPeriodException("No period " + periodId);
        }
        period.set(found);
    }
}
